using Alterverse.AI;using Alterverse.CameraSystem;using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Match;using Alterverse.UI;using Alterverse.Visuals;using UnityEngine;
using CombatFeedbackComponent=Alterverse.Combat.CombatFeedback;using FrontHudComponent=Alterverse.Match.DimensionsFrontHUD;
namespace Alterverse.Prototype
{
public sealed class PrototypeBootstrap:MonoBehaviour
{
[SerializeField]private bool buildOnStart=true;[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<PrototypeBootstrap>()==null)new GameObject("AV_PrototypeBootstrap").AddComponent<PrototypeBootstrap>();}private System.Collections.IEnumerator Start(){if(!buildOnStart)yield break;yield return null;while(MainMenuController.IsVisible)yield return null;BuildPrototype();}
public System.Collections.IEnumerator RestartPrototype()
{
Time.timeScale=0f;
GameObject previous=GameObject.Find("DF_MatchWorld");
if(previous!=null){previous.SetActive(false);Destroy(previous);}
yield return null;
BuildPrototype();Time.timeScale=1f;
}
public void BuildPrototype(){if(GameObject.Find("AV_Player")!=null)return;
var existing=new System.Collections.Generic.HashSet<GameObject>(gameObject.scene.GetRootGameObjects());
GameObject world=new GameObject("DF_MatchWorld");
BuildArena();GameObject player=GameObject.CreatePrimitive(PrimitiveType.Capsule);player.name="AV_Player";player.transform.position=new Vector3(-32,1,-4);Destroy(player.GetComponent<CapsuleCollider>());CharacterController cc=player.AddComponent<CharacterController>();cc.height=2;cc.radius=.5f;HeroId selected=PlayerHeroSelection.Selected;player.AddComponent<HeroIdentity>().Configure(selected);HeroCombatProfile profile=player.AddComponent<HeroCombatProfile>();profile.Configure(selected);player.AddComponent<HeroAbilityKit>().Configure(selected);Health ph=player.AddComponent<Health>();ph.Configure(profile.Health);player.AddComponent<TeamMember>().Initialize(0);player.AddComponent<HeroMotor>();player.AddComponent<HeroRespawn>();player.AddComponent<BasicAttack>();player.AddComponent<PlayerHeroAbilities>();SetColor(player,Color.Lerp(StylizedArtDirection.HeroAccent(selected),StylizedArtDirection.ZeroDark,.45f));Renderer playerPlaceholder=player.GetComponent<Renderer>();if(playerPlaceholder!=null)playerPlaceholder.enabled=false;player.AddComponent<CombatFeedbackComponent>();player.AddComponent<StylizedHeroVisual>().Build();SpawnHealingZone zeroZone=GameObject.Find("AV_ZeroSpawnZone")?.GetComponent<SpawnHealingZone>();if(zeroZone!=null){zeroZone.InitializeTeam(0);zeroZone.Initialize(ph);}SpawnHealingZone lumenZone=GameObject.Find("AV_LumenSpawnZone")?.GetComponent<SpawnHealingZone>();if(lumenZone!=null)lumenZone.InitializeTeam(1);UnityEngine.Camera cam=UnityEngine.Camera.main;if(cam==null){GameObject c=new("Main Camera");c.tag="MainCamera";cam=c.AddComponent<UnityEngine.Camera>();}cam.backgroundColor=StylizedArtDirection.Ink;MobaCamera mc=cam.GetComponent<MobaCamera>()??cam.gameObject.AddComponent<MobaCamera>();mc.SetTarget(player.transform);new GameObject("AV_HUD").AddComponent<PrototypeHUD>().Initialize(ph,null,null);new GameObject("DF_TargetIndicator").AddComponent<TargetIndicatorHUD>();new GameObject("DF_HeroTeamMarkers").AddComponent<HeroTeamMarkers>();new GameObject("AV_LaneWaveSpawner").AddComponent<LaneWaveSpawner>();new GameObject("AV_5v5Roster").AddComponent<FiveVsFiveTestRoster>();new GameObject("AV_DimensionsFront").AddComponent<DimensionsFront>();new GameObject("AV_DimensionsFrontCombatBridge").AddComponent<DimensionsFrontCombatBridge>();new GameObject("AV_DimensionsFrontVisual").AddComponent<DimensionsFrontVisual>();new GameObject("AV_DimensionsFrontHUD").AddComponent<FrontHudComponent>();new GameObject("DF_OvertimePresentation").AddComponent<OvertimePresentation>();new GameObject("DF_DimensionPlanetDirector").AddComponent<DimensionPlanetDirector>();new GameObject("DF_PlanetHUD").AddComponent<PlanetHUD>();new GameObject("AV_MatchTelemetry").AddComponent<MatchTelemetry>();new GameObject("AV_MatchScoreboard").AddComponent<MatchScoreboard>();new GameObject("AV_MatchOpening").AddComponent<MatchOpening>();
foreach(GameObject created in gameObject.scene.GetRootGameObjects())
if(created!=world&&!existing.Contains(created))created.transform.SetParent(world.transform,true);
}
private static void BuildArena(){Color lane=Color.Lerp(StylizedArtDirection.ZeroMid,StylizedArtDirection.LumenMid,.5f);CreateGround("AV_DimensionZeroGround",new Vector3(-21,-.12f,0),new Vector3(42,.2f,72),StylizedArtDirection.ZeroDark);CreateGround("AV_LumenGround",new Vector3(21,-.12f,0),new Vector3(42,.2f,72),StylizedArtDirection.LumenDark);CreateLane("AV_TopLane",16,lane);CreateLane("AV_BotLane",-16,lane);CreateVisualBlock("DF_CentralFrontZone",new Vector3(0,.035f,0),new Vector3(30,.045f,12),Color.Lerp(StylizedArtDirection.ZeroMid,StylizedArtDirection.LumenMid,.45f),Vector3.zero);CreateVisualBlock("AV_ZeroBasePad",new Vector3(-36,.04f,0),new Vector3(8,.05f,28),StylizedArtDirection.ZeroMid,Vector3.zero);CreateVisualBlock("AV_LumenBasePad",new Vector3(36,.04f,0),new Vector3(8,.05f,28),StylizedArtDirection.LumenMid,Vector3.zero);CreateBaseCore(new Vector3(-36,1.15f,0),StylizedArtDirection.ZeroEnergy,"DF_ZeroRealityCore",true,0);CreateBaseCore(new Vector3(36,1.15f,0),StylizedArtDirection.LumenEnergy,"DF_LumenRealityCore",false,1);CreateSpawnZone(new Vector3(-34,.07f,-4),StylizedArtDirection.ZeroEnergy,"AV_ZeroSpawnZone");CreateSpawnZone(new Vector3(34,.07f,4),StylizedArtDirection.LumenEnergy,"AV_LumenSpawnZone");CreateTowers();for(int i=-5;i<=5;i++){float z=i*2.1f,x=Mathf.Sin(i*1.73f)*.65f;CreateVisualBlock("AV_RealityScar",new Vector3(x,.055f,z),new Vector3(.34f,.045f,1.5f),StylizedArtDirection.ZeroEnergy,new Vector3(0,Mathf.Sin(i)*13,0));}CreateObjectiveZone(new Vector3(0,.07f,4),StylizedArtDirection.LumenEnergy,"DF_CentralPlanetArena");CreateCentralHealing();new GameObject("DF_StylizedArenaOverlay").AddComponent<StylizedArenaOverlay>();new GameObject("DF_ArenaAtmosphere").AddComponent<ArenaAtmosphere>();new GameObject("DF_DimensionArenaArchitecture").AddComponent<DimensionArenaArchitecture>();new GameObject("DF_RealityCollisionLandmarks").AddComponent<RealityCollisionLandmarks>();}
private static void CreateSpawnZone(Vector3 p,Color c,string n){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=new Vector3(4.5f,.025f,4.5f);DisableCollider(g);SetColor(g,c);g.AddComponent<SpawnHealingZone>();g.AddComponent<HealingZoneMarker>();}private static void CreateLane(string n,float z,Color c){CreateVisualBlock(n,new Vector3(0,.035f,z),new Vector3(72,.045f,3f),c,Vector3.zero);CreateVisualBlock(n+"_ZeroConnector",new Vector3(-30,.04f,z*.7f),new Vector3(15,.045f,1.8f),c,new Vector3(0,z>0?-16:16,0));CreateVisualBlock(n+"_LumenConnector",new Vector3(30,.04f,z*.7f),new Vector3(15,.045f,1.8f),c,new Vector3(0,z>0?16:-16,0));}private static void CreateTowers(){float[] lanes={16,-16};foreach(float z in lanes){CreateTower(new Vector3(-25,1.25f,z),0,StylizedArtDirection.ZeroMid,"AV_ZeroBastion");CreateTower(new Vector3(25,1.25f,z),1,StylizedArtDirection.LumenMid,"AV_LumenBastion");}}private static void CreateTower(Vector3 p,int team,Color c,string n){GameObject t=GameObject.CreatePrimitive(PrimitiveType.Cylinder);t.name=n;t.transform.position=p;t.transform.localScale=new Vector3(1.05f,1.45f,1.05f);SetColor(t,Color.Lerp(c,StylizedArtDirection.Ink,.68f));Health h=t.AddComponent<Health>();h.Configure(800,true);t.AddComponent<LaneTower>().Initialize(team);t.AddComponent<DimensionTowerShell>().Build(team);CreateVisualCylinder(n+"_Base",new Vector3(p.x,.08f,p.z),new Vector3(1.55f,.04f,1.55f),c);}private static void CreateObjectiveZone(Vector3 p,Color c,string n){CreateVisualCylinder(n,p,new Vector3(3.2f,.025f,3.2f),c);for(int i=0;i<6;i++){float a=i*60*Mathf.Deg2Rad;CreateShard(p+new Vector3(Mathf.Cos(a)*2.5f,.55f,Mathf.Sin(a)*2.5f),c,.4f,true);}}private static void CreateCentralHealing(){GameObject heal=new GameObject("DF_CentralHealingPickup");heal.transform.position=new Vector3(0,.12f,0);heal.AddComponent<CentralHealingPickup>();}private static void CreateBaseCore(Vector3 p,Color c,string n,bool zero,int team){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=new Vector3(2.15f,1.85f,2.15f);SetColor(g,Color.Lerp(c,StylizedArtDirection.Ink,.55f));Health h=g.AddComponent<Health>();h.Configure(5000,true);g.AddComponent<RealityCore>().Initialize(team);g.AddComponent<RealityCoreShell>().Build(zero);}private static void CreateGround(string n,Vector3 p,Vector3 s,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;SetColor(g,c);}private static void CreateShard(Vector3 p,Color c,float size,bool animated){GameObject s=GameObject.CreatePrimitive(PrimitiveType.Cube);s.name="AV_RiftShard";s.transform.position=p;s.transform.localScale=new Vector3(size*.35f,size,size*.35f);s.transform.rotation=Quaternion.Euler(20,45,25);DisableCollider(s);SetColor(s,c);if(animated)s.AddComponent<MapAmbientVisual>();}private static void CreateVisualCylinder(string n,Vector3 p,Vector3 s,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=s;DisableCollider(g);SetColor(g,c);}private static void CreateVisualBlock(string n,Vector3 p,Vector3 s,Color c,Vector3 r){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;g.transform.rotation=Quaternion.Euler(r);DisableCollider(g);SetColor(g,c);}private static void DisableCollider(GameObject g){Collider c=g.GetComponent<Collider>();if(c!=null)c.enabled=false;}private static void SetColor(GameObject g,Color c){Renderer r=g.GetComponent<Renderer>();if(r!=null)r.material.color=c;}
}}
